('lib/content/gpx_scolarite/dps_dpg/generalite_pages/tentative/condition_tentative_page.dart','f00016','I. Un commencement d’exécution',16,'TextSpan','son acte est constitutif d’un commencement d’exécution.','son acte est constitutif d’un commencement d’exécution.','{"font_weight_hints":["FontWeight.w700"]}'::jsonb,true),
('lib/content/gpx_scolarite/dps_dpg/generalite_pages/tentative/condition_tentative_page.dart','f00017','I. Un commencement d’exécution',17,'TextSpan',' S’il n’en avait pas été empêché, on est en droit de penser qu’il serait allé jusqu’au bout de son forfait, c’est-à-dire voler des objets.',' S’il n’en avait pas été empêché, on est en droit de penser qu’il serait allé jusqu’au bout de son forfait, c’est-à-dire voler des objets.','{"font_weight_hints":["FontWeight.w700"]}'::jsonb,true),
